import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  SafeAreaView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const DashboardScreen = ({ navigation }) => {
  const [recentWorkouts, setRecentWorkouts] = useState([]);
  const [todayStats, setTodayStats] = useState({
    workouts: 0,
    exercises: 0,
    totalTime: 0,
  });

  useEffect(() => {
    // Load recent workouts and stats
    loadDashboardData();
  }, []);

  const loadDashboardData = () => {
    // TODO: Load from local storage
    setRecentWorkouts([
      { 
        id: 1, 
        type: 'Weightlifting', 
        date: '8/4/2025', 
        duration: 2, 
        exercises: 3,
        ratings: {
          beforeMood: 5,
          beforeEnergy: 5,
          afterMood: 7,
          afterEnergy: 6,
          workoutRating: 8
        }
      },
      { 
        id: 2, 
        type: 'Cardio', 
        date: '8/4/2025', 
        duration: 1, 
        exercises: 1,
        ratings: {
          beforeMood: 4,
          beforeEnergy: 6,
          afterMood: 8,
          afterEnergy: 7,
          workoutRating: 9
        }
      },
    ]);
  };

  const startNewWorkout = () => {
    navigation.navigate('Workout');
  };

  // Helper function to get color based on rating
  const getRatingColor = (rating) => {
    if (rating >= 7) return '#28a745'; // Green
    if (rating >= 4) return '#ffc107'; // Yellow
    return '#dc3545'; // Red
  };

  // Helper function to get gradient color for mood/energy shift
  const getShiftColor = (pre, post) => {
    const shift = post - pre;
    if (shift >= 2) return '#28a745'; // Green - significant improvement
    if (shift >= 0) return '#17a2b8'; // Blue - slight improvement
    if (shift >= -1) return '#ffc107'; // Yellow - slight decline
    return '#dc3545'; // Red - significant decline
  };

  // Helper function to calculate average shift
  const getAverageShift = (workout) => {
    const moodShift = workout.ratings.afterMood - workout.ratings.beforeMood;
    const energyShift = workout.ratings.afterEnergy - workout.ratings.beforeEnergy;
    return (moodShift + energyShift) / 2;
  };

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView style={styles.scrollView}>
        {/* Header */}
        <View style={styles.header}>
          <Text style={styles.title}>Workout Journal</Text>
          <Text style={styles.subtitle}>Track your fitness journey</Text>
        </View>

        {/* Quick Actions */}
        <View style={styles.quickActions}>
          <TouchableOpacity style={styles.actionButton} onPress={startNewWorkout}>
            <Ionicons name="add-circle" size={24} color="#007AFF" />
            <Text style={styles.actionText}>Start Workout</Text>
          </TouchableOpacity>
          
          <TouchableOpacity style={styles.actionButton}>
            <Ionicons name="analytics" size={24} color="#007AFF" />
            <Text style={styles.actionText}>View Progress</Text>
          </TouchableOpacity>
        </View>

        {/* Today's Stats */}
        <View style={styles.statsContainer}>
          <Text style={styles.sectionTitle}>Today's Stats</Text>
          <View style={styles.statsGrid}>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>{todayStats.workouts}</Text>
              <Text style={styles.statLabel}>Workouts</Text>
            </View>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>{todayStats.exercises}</Text>
              <Text style={styles.statLabel}>Exercises</Text>
            </View>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>{todayStats.totalTime}</Text>
              <Text style={styles.statLabel}>Minutes</Text>
            </View>
          </View>
        </View>

        {/* Recent Workouts */}
        <View style={styles.recentContainer}>
          <Text style={styles.sectionTitle}>Recent Workouts</Text>
          {recentWorkouts.map((workout) => (
            <View key={workout.id} style={styles.workoutCard}>
              <View style={styles.workoutHeader}>
                <Text style={styles.workoutType}>{workout.type}</Text>
                <Text style={styles.workoutDate}>{workout.date}</Text>
              </View>
              
              {/* Rating Circle */}
              <View style={styles.ratingContainer}>
                <View style={[styles.ratingCircle, { borderColor: getRatingColor(workout.ratings.workoutRating) }]}>
                  <Text style={[styles.ratingText, { color: getRatingColor(workout.ratings.workoutRating) }]}>
                    {workout.ratings.workoutRating}
                  </Text>
                </View>
                <Text style={styles.durationText}>{workout.duration} min</Text>
              </View>

              {/* Exercise Count */}
              <Text style={styles.exerciseCount}>{workout.exercises} exercises</Text>
              
              {/* Mood/Energy Shift Gradient */}
              <View style={styles.shiftContainer}>
                <View style={[styles.shiftGradient, { backgroundColor: getShiftColor(workout.ratings.beforeMood, workout.ratings.afterMood) }]}>
                  <Text style={styles.shiftLabel}>Mood</Text>
                  <Text style={styles.shiftValue}>{workout.ratings.beforeMood} → {workout.ratings.afterMood}</Text>
                </View>
                <View style={[styles.shiftGradient, { backgroundColor: getShiftColor(workout.ratings.beforeEnergy, workout.ratings.afterEnergy) }]}>
                  <Text style={styles.shiftLabel}>Energy</Text>
                  <Text style={styles.shiftValue}>{workout.ratings.beforeEnergy} → {workout.ratings.afterEnergy}</Text>
                </View>
              </View>
            </View>
          ))}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f8f9fa',
  },
  scrollView: {
    flex: 1,
  },
  header: {
    padding: 20,
    backgroundColor: '#fff',
    borderBottomWidth: 1,
    borderBottomColor: '#e9ecef',
  },
  title: {
    fontSize: 28,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 5,
  },
  subtitle: {
    fontSize: 16,
    color: '#666',
  },
  quickActions: {
    flexDirection: 'row',
    padding: 20,
    gap: 15,
  },
  actionButton: {
    flex: 1,
    backgroundColor: '#fff',
    padding: 20,
    borderRadius: 12,
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  actionText: {
    marginTop: 8,
    fontSize: 14,
    fontWeight: '600',
    color: '#333',
  },
  statsContainer: {
    padding: 20,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 15,
  },
  statsGrid: {
    flexDirection: 'row',
    gap: 15,
  },
  statCard: {
    flex: 1,
    backgroundColor: '#fff',
    padding: 20,
    borderRadius: 12,
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  statNumber: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#007AFF',
  },
  statLabel: {
    fontSize: 12,
    color: '#666',
    marginTop: 5,
  },
  recentContainer: {
    padding: 20,
  },
  workoutCard: {
    backgroundColor: '#fff',
    borderRadius: 12,
    padding: 16,
    marginBottom: 12,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  workoutHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 12,
  },
  workoutType: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#333',
  },
  workoutDate: {
    fontSize: 14,
    color: '#666',
  },
  ratingContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  ratingCircle: {
    width: 40,
    height: 40,
    borderRadius: 20,
    borderWidth: 3,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#fff',
  },
  ratingText: {
    fontSize: 16,
    fontWeight: 'bold',
  },
  durationText: {
    fontSize: 14,
    color: '#666',
    fontWeight: '500',
  },
  exerciseCount: {
    fontSize: 14,
    color: '#666',
    marginBottom: 12,
  },
  shiftContainer: {
    flexDirection: 'row',
    gap: 8,
  },
  shiftGradient: {
    flex: 1,
    padding: 8,
    borderRadius: 8,
    alignItems: 'center',
  },
  shiftLabel: {
    fontSize: 12,
    color: '#fff',
    fontWeight: '600',
    marginBottom: 2,
  },
  shiftValue: {
    fontSize: 11,
    color: '#fff',
    fontWeight: '500',
  },
});

export default DashboardScreen;
